package ui

import (
	"bytes"
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"errors"
	"fmt"
	"html/template"
	"io/fs"
	"log/slog"
	"mime"
	"net/http"
	"net/url"
	"path"
	"strings"
	"time"

	"github.com/cosmic-chimps/caravana/internal/httpx"
	"github.com/cosmic-chimps/caravana/internal/service"
)

// The pages and their assets are compiled into the binary (C#: embedded
// resources). static/app.css is generated by tools/ui-css.sh and committed.
//
//go:embed templates/*.html
var templatesFS embed.FS

//go:embed static
var staticFS embed.FS

func init() {
	// Go's built-in table doesn't know woff2, and the host's might not either.
	_ = mime.AddExtensionType(".woff2", "font/woff2")
}

// Deps is what the pages need.
type Deps struct {
	Auth    *service.Auth
	Proxies httpx.Proxies
	Log     *slog.Logger
	// Now is the clock for the relative times on the pages; nil means
	// time.Now. Tests give it the same fake clock as the Auth.
	Now func() time.Time
}

type server struct {
	now     func() time.Time
	auth    *service.Auth
	proxies httpx.Proxies
	log     *slog.Logger
	pages   map[string]*template.Template
	static  fs.FS
	cssHash string // content hash of app.css, the ?v= cache-buster
	csrf    *http.CrossOriginProtection
}

// New serves /login, /logout, /account, / (a redirect) and /static/….
//
// Every state-changing request passes http.CrossOriginProtection first: it
// refuses a request the browser marks as coming from another site, by the
// Sec-Fetch-Site and Origin headers a page on another site can't forge. (C#:
// ASP.NET's antiforgery tokens; here the browser itself vouches, so no token
// has to be threaded through every form.)
func New(d Deps) (http.Handler, error) {
	s := &server{auth: d.Auth, proxies: d.Proxies, log: d.Log, now: d.Now, csrf: http.NewCrossOriginProtection()}
	if s.now == nil {
		s.now = time.Now
	}

	sub, err := fs.Sub(staticFS, "static")
	if err != nil {
		return nil, err
	}
	s.static = noDirs{sub}
	css, err := fs.ReadFile(sub, "app.css")
	if err != nil {
		return nil, fmt.Errorf("read app.css: %w", err)
	}
	sum := sha256.Sum256(css)
	s.cssHash = hex.EncodeToString(sum[:])[:12]

	if s.pages, err = parseTemplates(); err != nil {
		return nil, err
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /{$}", func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, "/account", http.StatusSeeOther)
	})
	mux.HandleFunc("GET /login", s.showLogin)
	mux.HandleFunc("POST /login", s.protected(s.signIn))
	mux.HandleFunc("POST /logout", s.protected(s.signOut))
	mux.HandleFunc("GET /account", s.requireSession(s.showAccount))
	mux.HandleFunc("POST /account/password", s.protected(s.requireSession(s.changePassword)))
	mux.HandleFunc("POST /account/tokens", s.protected(s.requireSession(s.createToken)))
	mux.HandleFunc("POST /account/tokens/{id}/revoke", s.protected(s.requireSession(s.revokeToken)))
	mux.Handle("GET /static/", http.StripPrefix("/static/", s.serveStatic()))
	mux.HandleFunc("/", s.notFound)
	return s.securityHeaders(mux), nil
}

// parseTemplates builds one template set per page: the shared base, plus the
// page's own "content". html/template escapes every value for where it lands
// (HTML text, attribute, URL), like Razor's @.
func parseTemplates() (map[string]*template.Template, error) {
	pages := map[string]*template.Template{}
	for _, name := range []string{"login", "account", "message"} {
		t, err := template.New("base.html").ParseFS(templatesFS, "templates/base.html", "templates/"+name+".html")
		if err != nil {
			return nil, fmt.Errorf("parse template %s: %w", name, err)
		}
		pages[name] = t
	}
	return pages, nil
}

// pageData is what every page shows: its title and the stylesheet's URL.
type pageData struct {
	Title string
	CSS   string
}

func (s *server) page(title string) pageData {
	return pageData{Title: title, CSS: "/static/app.css?v=" + s.cssHash}
}

// render writes a page. Rendering to a buffer first means a template error
// gives a clean 500 instead of a half-written page.
func (s *server) render(w http.ResponseWriter, status int, name string, data any) {
	var buf bytes.Buffer
	if err := s.pages[name].ExecuteTemplate(&buf, "base", data); err != nil {
		s.log.Error("render page", "page", name, "error", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(status)
	_, _ = w.Write(buf.Bytes())
}

// messageData is the plain page for refusals and errors.
type messageData struct {
	pageData
	Heading string
	Text    string
}

func (s *server) message(w http.ResponseWriter, status int, title, heading, text string) {
	s.render(w, status, "message", messageData{pageData: s.page(title), Heading: heading, Text: text})
}

func (s *server) notFound(w http.ResponseWriter, r *http.Request) {
	s.message(w, http.StatusNotFound, "Not found", "That page doesn't exist.", "Check the address, or go back to the account page.")
}

func (s *server) serverError(w http.ResponseWriter, what string, err error) {
	s.log.Error(what, "error", err)
	s.message(w, http.StatusInternalServerError, "Something went wrong",
		"Something went wrong.", "caravana couldn't finish that. The details are in the server log.")
}

// securityHeaders sets, on every response, what keeps the pages in their own
// origin (research R12): nothing is loaded from elsewhere, nothing frames
// them, forms post only to caravana.
func (s *server) securityHeaders(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h := w.Header()
		h.Set("Content-Security-Policy", "default-src 'self'; frame-ancestors 'none'; form-action 'self'; base-uri 'none'")
		h.Set("X-Content-Type-Options", "nosniff")
		h.Set("Referrer-Policy", "same-origin")
		next.ServeHTTP(w, r)
	})
}

// noDirs hides directories from the file server, which would list them.
type noDirs struct{ fs.FS }

func (n noDirs) Open(name string) (fs.File, error) {
	f, err := n.FS.Open(name)
	if err != nil {
		return nil, err
	}
	if info, err := f.Stat(); err != nil || info.IsDir() {
		f.Close()
		return nil, fs.ErrNotExist
	}
	return f, nil
}

// serveStatic serves the embedded stylesheet and fonts. The stylesheet is
// addressed with its content hash (?v=…), so it can be cached for a year: a
// new build has a new URL. The fonts' names change if the fonts do.
func (s *server) serveStatic() http.Handler {
	files := http.FileServerFS(s.static)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if path.Ext(r.URL.Path) == ".woff2" || (r.URL.Path == "app.css" && r.URL.Query().Get("v") != "") {
			w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		} else {
			w.Header().Set("Cache-Control", "no-cache")
		}
		files.ServeHTTP(w, r)
	})
}

// protected refuses a state-changing request the browser says came from
// another site, with a page, before anything changes.
func (s *server) protected(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		if err := s.csrf.Check(r); err != nil {
			s.message(w, http.StatusForbidden, "Request refused", "That request was refused.",
				"It came from another site, so caravana didn't act on it. Nothing was changed.")
			return
		}
		next(w, r)
	}
}

// sessionState says what the request's cookie amounts to.
type sessionState int

const (
	noSession    sessionState = iota // no cookie
	endedSession                     // a cookie, but its session ended or never existed
	validSession                     // signed in
)

// current checks the request's session cookie. The cookie's value comes back
// too, for the calls that act on that session.
func (s *server) current(r *http.Request) (value string, state sessionState, err error) {
	value, ok := httpx.SessionCookie(r, s.proxies.HTTPS(r))
	if !ok {
		return "", noSession, nil
	}
	switch err := s.auth.CheckSession(r.Context(), value); {
	case err == nil:
		return value, validSession, nil
	case errors.Is(err, service.ErrNotAuthenticated):
		return value, endedSession, nil
	default:
		return "", noSession, err
	}
}

// sessionHandler is a handler of a page that needs a signed-in admin; it gets
// the session's cookie value.
type sessionHandler func(w http.ResponseWriter, r *http.Request, session string)

// requireSession runs next for a signed-in admin, and otherwise sends the
// browser to /login, remembering where it was going (FR-011).
func (s *server) requireSession(next sessionHandler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		value, state, err := s.current(r)
		if err != nil {
			s.serverError(w, "check session", err)
			return
		}
		if state != validSession {
			// Only a page is worth coming back to: after a form post, the
			// browser would GET the form's URL, which isn't a page.
			var params []string
			if r.Method == http.MethodGet || r.Method == http.MethodHead {
				params = append(params, "next="+url.QueryEscape(r.URL.RequestURI()))
			}
			if state == endedSession {
				params = append(params, "expired=1")
			}
			to := "/login"
			if len(params) > 0 {
				to += "?" + strings.Join(params, "&")
			}
			http.Redirect(w, r, to, http.StatusSeeOther)
			return
		}
		next(w, r, value)
	}
}

// safeNext returns next if it is a path inside caravana a signed-in admin may
// be sent to, else "". It must be a plain path: not another host
// (//evil.example, /\evil, https://…), not an API route, and not the sign-in
// pages themselves (FR-011).
func safeNext(next string) string {
	if next == "" || next[0] != '/' || strings.HasPrefix(next, "//") || strings.ContainsAny(next, "\\\r\n\t") {
		return ""
	}
	u, err := url.Parse(next)
	if err != nil || u.Scheme != "" || u.Host != "" {
		return ""
	}
	switch p := u.Path; {
	case p == "/v1" || strings.HasPrefix(p, "/v1/"), p == "/login", p == "/logout":
		return ""
	}
	return next
}
